/**
 * How Sword Dharma wheel (`ken-rinpo`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/ken-rinpo";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Strike the hub and rim and divide them into six. Rule one large sword and two small points in each sector, adding small white openings. Place a round hole in the rim behind each large sword.","ja":"軸と輪を打って六等分します。各区画に大きな剣を一つと小さなとがりを二つ引き、白い小穴を置きます。剣の根に沿って輪にも丸い穴を置きます。"};

export default construction;
export { construction, description };
